import { pgTable, text, timestamp, uuid, boolean, jsonb } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

export const bookmarks = pgTable('bookmarks', {
  id: uuid('id').primaryKey().defaultRandom(),
  userId: text('user_id').notNull(),
  url: text('url').notNull().unique(),
  title: text('title').notNull(),
  shortSummary: text('short_summary'),
  detailedSummary: text('detailed_summary'),
  tags: jsonb('tags').$type<string[]>(),
  category: text('category'),
  language: text('language'),
  note: text('note'),
  content: text('content'),
  processed: boolean('processed').default(false),
  failed: boolean('failed').default(false),
  createdAt: timestamp('created_at').defaultNow(),
  updatedAt: timestamp('updated_at').defaultNow(),
});

// Full text search index
export const bookmarkSearchIndex = sql`CREATE INDEX IF NOT EXISTS bookmark_fts_idx ON ${bookmarks} USING gin(to_tsvector('english', title || ' ' || content || ' ' || coalesce(short_summary, '')));`;

'use server';

import { db } from '@/lib/db';

import { bookmarks } from '@/drizzle/schema';

import { normalizeUrl } from '@/lib/utils';
import { analyzeWithGemini } from '@/lib/gemini';
import { getUser } from '@stack-auth/stack';

export async function saveBookmark(formData: FormData) {
  const user = await getUser();
  if (!user) throw new Error('Unauthorized');

  const url = formData.get('url') as string;
  const note = formData.get('note') as string | null;

  const cleanUrl = normalizeUrl(url);

  // Check for duplicate
  const existing = await db.query.bookmarks.findFirst({
    where: (b, { eq }) => eq(b.url, cleanUrl)
  });

  if (existing) return { success: false, error: 'Bookmark already exists' };

  const analysis = await analyzeWithGemini(cleanUrl);

  await db.insert(bookmarks).values({
    userId: user.id,
    url: cleanUrl,
    title: analysis.title,
    shortSummary: analysis.shortSummary,
    detailedSummary: analysis.detailedSummary,
    tags: analysis.tags,
    category: analysis.category,
    language: analysis.language,
    note: note || null,
    content: analysis.content,
    processed: true,
  });

  return { success: true };
}

