import { describe, it, expect } from 'vitest';
import { normalizeUrl } from '@/lib/utils';

describe('normalizeUrl', () => {
  it('removes tracking parameters', () => {
    const result = normalizeUrl('https://example.com/article?utm_source=twitter&utm_campaign=spring');
    expect(result).toBe('https://example.com/article');
  });

  it('removes www prefix', () => {
    const result = normalizeUrl('https://www.example.com/blog/post-1');
    expect(result).toBe('https://example.com/blog/post-1');
  });

  it('handles invalid URLs gracefully', () => {
    const result = normalizeUrl('not-a-url');
    expect(result).toBe('not-a-url');
  });

  it('normalizes trailing slashes consistently', () => {
    const result = normalizeUrl('https://example.com/');
    expect(result).toBe('https://example.com');
  });
});
